function view(string $name, array $data = []): never
{
    extract($data, EXTR_SKIP);
    require ROOT_PATH . '/src/views/' . $name . '.php';
    exit;
}

function tenant_by_slug(string $slug, bool $published = true): ?array
{
    $sql = 'SELECT * FROM tenants WHERE slug=:slug' . ($published ? ' AND published_at IS NOT NULL AND suspended_at IS NULL' : '') . ' LIMIT 1';
    $stmt = db()->prepare($sql); $stmt->execute(['slug'=>$slug]);
    $tenant=$stmt->fetch() ?: null;
    if($tenant&&$published&&$tenant['store_open']){
        $days=[(int)date('w'),((int)date('w')+6)%7];$hours=db()->prepare('SELECT weekday,opens_at,closes_at,closed FROM business_hours WHERE tenant_id=:tenant AND weekday IN (:today,:yesterday)');$hours->execute(['tenant'=>$tenant['id'],'today'=>$days[0],'yesterday'=>$days[1]]);$schedule=array_column($hours->fetchAll(),null,'weekday');
        if($schedule){$now=date('H:i:s');$today=$schedule[$days[0]]??null;$yesterday=$schedule[$days[1]]??null;$openToday=$today&&!$today['closed']&&$today['opens_at']&&$today['closes_at']&&($today['opens_at']<=$today['closes_at']?($now>=$today['opens_at']&&$now<=$today['closes_at']):$now>=$today['opens_at']);$openOvernight=$yesterday&&!$yesterday['closed']&&$yesterday['opens_at']>$yesterday['closes_at']&&$now<=$yesterday['closes_at'];$tenant['store_open']=($openToday||$openOvernight)?1:0;}
    }
    return $tenant;
}

function login_allowed(string $email): bool
{
    $identity = hash('sha256', strtolower($email)); $ip = client_ip_hash();
    $stmt = db()->prepare('SELECT COUNT(*) identity_failures,COALESCE(SUM(CASE WHEN ip_hash=:ip THEN 1 ELSE 0 END),0) source_failures FROM login_attempts WHERE identity_hash=:identity AND successful=0 AND created_at > DATE_SUB(NOW(), INTERVAL 15 MINUTE)');
    $stmt->execute(compact('identity','ip'));
    $failures=$stmt->fetch()?:['identity_failures'=>0,'source_failures'=>0];
    return (int)$failures['source_failures']<8&&(int)$failures['identity_failures']<20;
}

function record_suspicious_login_attempt(array $user, string $identityHash): void
{
    $count=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE identity_hash=:identity AND successful=0 AND created_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$count->execute(['identity'=>$identityHash]);$attempts=(int)$count->fetchColumn();
    if($attempts<5||!rate_limit('suspicious-login-alert:'.$user['tenant_id'].':'.$user['id'],1,1800))return;
    try{audit((int)$user['tenant_id'],(int)$user['id'],'suspicious','login_attempt',null,['attempts'=>$attempts]);issue_suspicious_login_alert($user,$attempts);}catch(Throwable $error){error_log('[mjdev] suspicious login alert failure: '.get_class($error));}
}

function complete_authenticated_login(array $user, ?string $requestedDestination): never
{
    start_authenticated_session((int)$user['id'],(int)$user['tenant_id'],(int)$user['session_version']);unset($_SESSION['pending_two_factor']);
    db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=:id AND tenant_id=:tenant')->execute(['id'=>$user['id'],'tenant'=>$user['tenant_id']]);audit((int)$user['tenant_id'],(int)$user['id'],'login','user',(int)$user['id']);
    if(privileged_two_factor_required($user)){unset($_SESSION['login_destination']);redirect('/admin?section=settings#seguranca-conta');}
    if($requestedDestination===null&&$user['role']==='platform_admin')redirect('/platform');$destination=authorized_login_destination($user,$requestedDestination);unset($_SESSION['login_destination']);redirect($destination);
}

