    $type=is_string($payload['type']??null)?$payload['type']:'';$dataId=(string)(raw_query_parameter('data.id')??'');$payloadData=is_array($payload['data']??null)?$payload['data']:[];$payloadDataId=is_scalar($payloadData['id']??null)?(string)$payloadData['id']:'';
