    $notificationId=is_scalar($payload['id']??null)?(string)$payload['id']:'';$eventKey=hash('sha256',$type.'|'.($notificationId!==''?$notificationId:$requestId).'|'.$dataId);$payloadHash=hash('sha256',$raw);
    try{
        $insert=db()->prepare("INSERT INTO billing_provider_events (provider,provider_event_key,event_type,resource_ref,request_id,payload_hash,status,attempts,last_attempt_at) VALUES ('mercadopago',:event_key,:event_type,:resource,:request_id,:payload_hash,'processing',1,NOW())");
        try{$insert->execute(['event_key'=>$eventKey,'event_type'=>$type,'resource'=>$dataId,'request_id'=>$requestId,'payload_hash'=>$payloadHash]);}
        catch(PDOException $error){
            if($error->getCode()!=='23000')throw $error;
            $eventQuery=db()->prepare("SELECT status,received_at FROM billing_provider_events WHERE provider='mercadopago' AND provider_event_key=:event_key LIMIT 1");$eventQuery->execute(['event_key'=>$eventKey]);$event=$eventQuery->fetch();
            if(!$event)throw $error;if(in_array($event['status'],['processed','ignored'],true))json_response(['status'=>'ok']);
            if($event['status']==='processing'&&strtotime((string)$event['received_at'])>time()-300)json_response(['status'=>'processing'],202);
            db()->prepare("UPDATE billing_provider_events SET status='processing',attempts=attempts+1,last_attempt_at=NOW(),error_code=NULL WHERE provider='mercadopago' AND provider_event_key=:event_key")->execute(['event_key'=>$eventKey]);
        }
        $subscription=mercadopago_request('GET','/preapproval/'.rawurlencode($dataId));$subscriptionId=is_scalar($subscription['id']??null)?trim((string)$subscription['id']):'';$externalReference=is_scalar($subscription['external_reference']??null)?trim((string)$subscription['external_reference']):'';$providerStatus=is_string($subscription['status']??null)?$subscription['status']:'';
        if(!hash_equals($dataId,$subscriptionId)||!preg_match('/^[a-f0-9]{64}$/',$externalReference))throw new RuntimeException('Assinatura externa inválida.');
        $statusMap=['pending'=>'pending','authorized'=>'active','paused'=>'past_due','canceled'=>'cancelled','cancelled'=>'cancelled'];$localStatus=$statusMap[$providerStatus]??null;
        if($localStatus===null){db()->prepare("UPDATE billing_provider_events SET status='ignored',processed_at=NOW(),error_code='unsupported_status' WHERE provider='mercadopago' AND provider_event_key=:event_key")->execute(['event_key'=>$eventKey]);json_response(['status'=>'ignored']);}
        $billingQuery=db()->prepare("SELECT tenant_id FROM tenant_billing_accounts WHERE provider='mercadopago' AND provider_subscription_ref=:subscription AND checkout_reference=:reference LIMIT 1");$billingQuery->execute(['subscription'=>$subscriptionId,'reference'=>$externalReference]);$billingTenant=$billingQuery->fetchColumn();
        if(!$billingTenant){db()->prepare("UPDATE billing_provider_events SET status='ignored',processed_at=NOW(),error_code='unmatched_subscription' WHERE provider='mercadopago' AND provider_event_key=:event_key")->execute(['event_key'=>$eventKey]);json_response(['status'=>'ignored']);}
        $payerRef=is_scalar($subscription['payer_id']??null)?substr((string)$subscription['payer_id'],0,190):null;$autoRecurring=is_array($subscription['auto_recurring']??null)?$subscription['auto_recurring']:[];$periodStart=mercadopago_datetime($autoRecurring['start_date']??null);$periodEnd=mercadopago_datetime($subscription['next_payment_date']??null);
        $pdo=db();$pdo->beginTransaction();try{
