            $pdo->prepare("UPDATE billing_provider_events SET tenant_id=:tenant,status='processed',processed_at=NOW(),error_code=NULL WHERE provider='mercadopago' AND provider_event_key=:event_key")->execute(['tenant'=>$billingTenant,'event_key'=>$eventKey]);audit((int)$billingTenant,null,'webhook','tenant_billing_account',(int)$billingTenant,['provider'=>'mercadopago','status'=>$localStatus]);$pdo->commit();
