if (str_starts_with($path,'/admin/') && $method === 'POST') {
    $user=require_auth(); require_csrf(); $tenant=(int)$user['tenant_id']; $action=substr($path,7);
    $twoFactorSetupActions=['account/two-factor','account/email-verification','account/password','account/session/revoke','account/session/revoke-others','account/security-alerts','account/two-factor-recovery-codes'];
    if(privileged_two_factor_required($user)&&!in_array($action,$twoFactorSetupActions,true)){flash('error','Ative a verificação em duas etapas antes de continuar.');redirect('/admin?section=settings#seguranca-conta');}
    $management=['platform_admin','owner','manager'];
    $operationalActions=['order/status','account/password','table-session/open','table-session/close'];
    if(!in_array($action,$operationalActions,true) && !in_array($user['role'],$management,true)){http_response_code(403);exit('Acesso negado.');}
    $restaurantActions=['area/save','table/save','table/status','table/qr/regenerate','table-session/open','table-session/close'];
    if(in_array($action,$restaurantActions,true) && !business_type_supports_restaurant_operations((string)$user['business_type'])){http_response_code(403);exit('Recurso exclusivo de estabelecimentos de alimentação.');}
    if(!role_allowed_for_business_type((string)$user['role'],(string)$user['business_type'])){http_response_code(403);exit('Função incompatível com o segmento do estabelecimento.');}
    if($action==='order/status' && !in_array($user['role'],['platform_admin','owner','manager','attendant','waiter','kitchen','pos','courier'],true)){http_response_code(403);exit('Acesso negado.');}
    if(in_array($action,['table-session/open','table-session/close'],true) && !in_array($user['role'],['platform_admin','owner','manager','attendant','waiter','pos'],true)){http_response_code(403);exit('Acesso negado.');}
    if($action==='billing/reconcile'){
        if(!in_array($user['role'],['platform_admin','owner'],true)){http_response_code(403);exit('Somente o proprietário pode consultar uma assinatura.');}
        if(!rate_limit('billing-reconcile:'.$tenant,10,3600)){flash('error','Muitas consultas de assinatura. Aguarde antes de tentar novamente.');redirect('/admin?section=billing');}
        $billingQuery=db()->prepare("SELECT plan_code,status,provider_subscription_ref,checkout_reference FROM tenant_billing_accounts WHERE tenant_id=:tenant AND provider='mercadopago' LIMIT 1");$billingQuery->execute(compact('tenant'));$billing=$billingQuery->fetch();
        $subscriptionRef=trim((string)($billing['provider_subscription_ref']??''));$checkoutReference=trim((string)($billing['checkout_reference']??''));$expectedPlanId=$billing?mercadopago_plan_id((string)$billing['plan_code']):null;
        if(!$billing||$subscriptionRef===''||$checkoutReference===''||$expectedPlanId===null||!preg_match('/^[A-Za-z0-9_-]{10,190}$/',$subscriptionRef)||!preg_match('/^[a-f0-9]{64}$/',$checkoutReference)){flash('error','Nenhuma assinatura pendente está disponível para consulta.');redirect('/admin?section=billing');}
        try{
            $subscription=mercadopago_request('GET','/preapproval/'.rawurlencode($subscriptionRef));$providerSubscriptionId=trim((string)($subscription['id']??''));$providerReference=trim((string)($subscription['external_reference']??''));$providerPlanId=trim((string)($subscription['preapproval_plan_id']??''));$providerStatus=is_string($subscription['status']??null)?$subscription['status']:'';
            if(!hash_equals($subscriptionRef,$providerSubscriptionId)||!hash_equals($checkoutReference,$providerReference)||!hash_equals($expectedPlanId,$providerPlanId))throw new RuntimeException('Assinatura externa incompatível.');
