        $optionInsert=$pdo->prepare('INSERT INTO order_item_options (order_item_id,option_item_id,option_group_name,option_item_name,option_sku,unit_price_cents,quantity,line_total_cents) VALUES (:order_item,:option,:group_name,:item_name,:sku,:price,:quantity,:total)');
        $optionStockUpdate=$pdo->prepare('UPDATE option_items SET stock_quantity=stock_quantity-:qty WHERE id=:option AND tenant_id=:tenant AND stock_quantity IS NOT NULL AND stock_quantity>=:required');
        $comboInsert=$pdo->prepare('INSERT INTO order_combo_items (order_id,combo_id,combo_name,unit_price_cents,quantity,line_total_cents) VALUES (:order,:combo,:name,:price,:quantity,:total)');
        $stockUpdate = $pdo->prepare('UPDATE products SET stock_quantity=stock_quantity-:qty WHERE id=:product AND tenant_id=:tenant AND stock_quantity IS NOT NULL');
        foreach ($lines as $line) {
            $itemInsert->execute(['order'=>$orderId,'product'=>$line['id'],'name'=>$line['name'],'price'=>$line['price'],'qty'=>$line['qty'],'notes'=>$line['notes']?:null,'total'=>$line['total']]);
            $orderItemId=(int)$pdo->lastInsertId();foreach($line['options'] as$option){$optionInsert->execute(['order_item'=>$orderItemId,'option'=>$option['id'],'group_name'=>$option['group_name'],'item_name'=>$option['name'],'sku'=>$option['sku'],'price'=>$option['charged_price'],'quantity'=>$line['qty'],'total'=>$option['charged_price']*$line['qty']]);if($option['stock']!==null){$optionStockUpdate->execute(['qty'=>$line['qty'],'required'=>$line['qty'],'option'=>$option['id'],'tenant'=>$tenant]);if($optionStockUpdate->rowCount()!==1)throw new DomainException('O estoque de uma variação mudou. Revise o pedido.');}}
            $stockUpdate->execute(['qty'=>$line['qty'],'product'=>$line['id'],'tenant'=>$tenant]);
            $balance=$pdo->prepare('SELECT stock_quantity FROM products WHERE id=:product AND tenant_id=:tenant');$balance->execute(['product'=>$line['id'],'tenant'=>$tenant]);$after=$balance->fetchColumn();
            if($after!==null&&$after!==false)$pdo->prepare("INSERT INTO stock_movements (tenant_id,product_id,movement_type,quantity,balance_after,reference,notes) VALUES (:tenant,:product,'exit',:quantity,:balance,:reference,'Venda')")->execute(['tenant'=>$tenant,'product'=>$line['id'],'quantity'=>-$line['qty'],'balance'=>(int)$after,'reference'=>$code]);
        }
        foreach($comboLines as$line){$comboInsert->execute(['order'=>$orderId,'combo'=>$line['id'],'name'=>$line['name'],'price'=>$line['price'],'quantity'=>$line['qty'],'total'=>$line['total']]);foreach($line['components'] as$component){$decrement=$component['quantity']*$line['qty'];$stockUpdate->execute(['qty'=>$decrement,'product'=>$component['product_id'],'tenant'=>$tenant]);$balance=$pdo->prepare('SELECT stock_quantity FROM products WHERE id=:product AND tenant_id=:tenant');$balance->execute(['product'=>$component['product_id'],'tenant'=>$tenant]);$after=$balance->fetchColumn();if($after!==null&&$after!==false)$pdo->prepare("INSERT INTO stock_movements (tenant_id,product_id,movement_type,quantity,balance_after,reference,notes) VALUES (:tenant,:product,'exit',:quantity,:balance,:reference,:notes)")->execute(['tenant'=>$tenant,'product'=>$component['product_id'],'quantity'=>-$decrement,'balance'=>(int)$after,'reference'=>$code,'notes'=>'Combo '.$line['name']]);}}
        if($phone!==''){
            $pdo->prepare('INSERT INTO customers (tenant_id,name,phone,email,order_count,lifetime_value_cents,last_order_at) VALUES (:tenant,:name,:phone,:email,1,:total,NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name),email=COALESCE(VALUES(email),email),order_count=order_count+1,lifetime_value_cents=lifetime_value_cents+VALUES(lifetime_value_cents),last_order_at=NOW()')->execute(['tenant'=>$tenant,'name'=>$name,'phone'=>$phone,'email'=>$email?:null,'total'=>$total]);
            $customerQuery=$pdo->prepare('SELECT id,order_count FROM customers WHERE tenant_id=:tenant AND phone=:phone FOR UPDATE');$customerQuery->execute(['tenant'=>$tenant,'phone'=>$phone]);$customer=$customerQuery->fetch();
            if($customer){
                $ownReferral=$pdo->prepare('SELECT id FROM customer_referrals WHERE tenant_id=:tenant AND referrer_customer_id=:customer FOR UPDATE');$ownReferral->execute(['tenant'=>$tenant,'customer'=>$customer['id']]);
                if(!$ownReferral->fetchColumn()){$ownToken=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO customer_referrals (tenant_id,referrer_customer_id,token_hash,token_encrypted) VALUES (:tenant,:customer,:hash,:encrypted)')->execute(['tenant'=>$tenant,'customer'=>$customer['id'],'hash'=>hash_hmac('sha256',$ownToken,env('APP_KEY','')),'encrypted'=>encrypt_secret($ownToken)]);}
                if(!$internal&&$referralToken!==''&&(int)$customer['order_count']===1){
                    $referralQuery=$pdo->prepare('SELECT cr.id,cr.referrer_customer_id FROM customer_referrals cr JOIN tenant_preferences tp ON tp.tenant_id=cr.tenant_id AND tp.referral_enabled=1 WHERE cr.tenant_id=:tenant AND cr.token_hash=:hash AND cr.active=1 FOR UPDATE');$referralQuery->execute(['tenant'=>$tenant,'hash'=>hash_hmac('sha256',$referralToken,env('APP_KEY',''))]);$referral=$referralQuery->fetch();
                    if($referral&&(int)$referral['referrer_customer_id']!==(int)$customer['id'])$pdo->prepare('INSERT IGNORE INTO referral_attributions (tenant_id,referral_id,referred_customer_id,order_id) VALUES (:tenant,:referral,:customer,:order)')->execute(['tenant'=>$tenant,'referral'=>$referral['id'],'customer'=>$customer['id'],'order'=>$orderId]);
                }
            }
        }
        $pdo->prepare("INSERT INTO order_status_history(order_id,status) VALUES (:order,'received')")->execute(['order'=>$orderId]);
        if ($couponCode !== ''&&!$rewardId) $pdo->prepare('UPDATE coupons SET usage_count=usage_count+1 WHERE tenant_id=:tenant AND code=:code')->execute(['tenant'=>$tenant,'code'=>$couponCode]);
        audit($tenant,null,'create','order',$orderId);
        queue_webhooks($tenant,'order.created',['event'=>'order.created','order'=>['id'=>$orderId,'code'=>$code,'type'=>$type,'status'=>'received','total_cents'=>$total,'created_at'=>date(DATE_ATOM)]]);
        $pdo->commit();
        json_response(['code'=>$code,'tracking_url'=>'/pedido/'.$token,'total_cents'=>$total],201);
    } catch (DomainException $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        json_response(['error'=>$e->getMessage()],422);
    } catch (Throwable) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        json_response(['error'=>'Não foi possível criar o pedido.'],500);
    }
}

if (preg_match('#^/pedido/([a-f0-9]{64})$#',$path,$m) && $method==='GET') {
    $s=db()->prepare('SELECT o.*,t.name tenant_name,t.slug tenant_slug,t.whatsapp tenant_whatsapp,t.address tenant_address FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE o.tracking_token_hash=:token AND o.tracking_revoked_at IS NULL AND o.tracking_expires_at>NOW() LIMIT 1');
    $s->execute(['token'=>hash('sha256',$m[1])]);$order=$s->fetch();
    if(!$order){http_response_code(404);view('not-found');}
    $items=db()->prepare('SELECT oi.product_name,oi.quantity,oi.notes,oi.line_total_cents,GROUP_CONCAT(oio.option_item_name ORDER BY oio.id SEPARATOR \' · \') options_text FROM order_items oi JOIN orders o ON o.id=oi.order_id LEFT JOIN order_item_options oio ON oio.order_item_id=oi.id WHERE oi.order_id=:order AND o.tenant_id=:tenant GROUP BY oi.id ORDER BY oi.id');
    $items->execute(['order'=>$order['id'],'tenant'=>$order['tenant_id']]);
    $orderItems=$items->fetchAll();
    $combos=db()->prepare("SELECT oci.combo_name product_name,oci.quantity,NULL notes,oci.line_total_cents,'Combo' options_text FROM order_combo_items oci JOIN orders o ON o.id=oci.order_id WHERE oci.order_id=:order AND o.tenant_id=:tenant ORDER BY oci.id");
    $combos->execute(['order'=>$order['id'],'tenant'=>$order['tenant_id']]);
    $orderItems=array_merge($orderItems,$combos->fetchAll());
    $history=db()->prepare('SELECT osh.status,osh.created_at FROM order_status_history osh JOIN orders o ON o.id=osh.order_id WHERE osh.order_id=:order AND o.tenant_id=:tenant ORDER BY osh.id');
    $history->execute(['order'=>$order['id'],'tenant'=>$order['tenant_id']]);
    $trackingPhoneHash=hash_hmac('sha256',preg_replace('/\D/','',(string)$order['customer_phone'])??'',env('APP_KEY',''));$rewardQuery=db()->prepare('SELECT reward_kind,code_encrypted,discount_type,discount_value,minimum_cents,expires_at,redeemed_at FROM customer_rewards WHERE tenant_id=:tenant AND customer_phone_hash=:phone AND redeemed_at IS NULL AND expires_at>=NOW() ORDER BY id DESC');$rewardQuery->execute(['tenant'=>$order['tenant_id'],'phone'=>$trackingPhoneHash]);$earnedRewards=[];foreach($rewardQuery->fetchAll() as$reward){try{$reward['code']=decrypt_secret($reward['code_encrypted']);$earnedRewards[]=$reward;}catch(Throwable){}}
    $referralUrl=null;$referralQuery=db()->prepare('SELECT cr.token_encrypted FROM customers c JOIN customer_referrals cr ON cr.referrer_customer_id=c.id AND cr.tenant_id=c.tenant_id AND cr.active=1 JOIN tenant_preferences tp ON tp.tenant_id=c.tenant_id AND tp.referral_enabled=1 WHERE c.tenant_id=:tenant AND c.phone=:phone LIMIT 1');$referralQuery->execute(['tenant'=>$order['tenant_id'],'phone'=>$order['customer_phone']]);$encryptedReferral=$referralQuery->fetchColumn();if($encryptedReferral){try{$referralUrl=rtrim(env('APP_URL','http://localhost'),'/').'/'.$order['tenant_slug'].'?ref='.decrypt_secret($encryptedReferral);}catch(Throwable){$referralUrl=null;}}
    header('Cache-Control: no-store, private');header('Referrer-Policy: no-referrer');
    view('tracking',['order'=>$order,'items'=>$orderItems,'history'=>$history->fetchAll(),'earnedRewards'=>$earnedRewards,'referralUrl'=>$referralUrl,'token'=>$m[1]]);
}

if(preg_match('#^/avaliar/([a-f0-9]{64})$#',$path,$m)&&$method==='GET'){$s=db()->prepare("SELECT o.id,o.tenant_id,o.customer_name,o.status,o.assigned_courier_id,t.name tenant_name FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE o.tracking_token_hash=:token AND o.tracking_revoked_at IS NULL AND o.tracking_expires_at>NOW() AND o.status='delivered' LIMIT 1");$s->execute(['token'=>hash('sha256',$m[1])]);$order=$s->fetch();if(!$order){http_response_code(404);view('not-found');}$items=db()->prepare('SELECT DISTINCT p.id,p.name,pr.id review_id,pr.rating,pr.comment FROM order_items oi JOIN products p ON p.id=oi.product_id LEFT JOIN product_reviews pr ON pr.order_id=oi.order_id AND pr.product_id=p.id WHERE oi.order_id=:order ORDER BY p.name');$items->execute(['order'=>$order['id']]);$courier=null;if($order['assigned_courier_id']){$c=db()->prepare('SELECT u.id,u.name,cr.id review_id,cr.rating,cr.comment FROM users u LEFT JOIN courier_reviews cr ON cr.courier_id=u.id AND cr.order_id=:order WHERE u.id=:courier AND u.tenant_id=:tenant AND u.role=\'courier\'');$c->execute(['order'=>$order['id'],'courier'=>$order['assigned_courier_id'],'tenant'=>$order['tenant_id']]);$courier=$c->fetch()?:null;}header('Cache-Control: no-store, private');header('Referrer-Policy: no-referrer');view('review',['order'=>$order,'items'=>$items->fetchAll(),'courier'=>$courier,'token'=>$m[1],'flash'=>take_flash()]);}

if(preg_match('#^/avaliar/([a-f0-9]{64})$#',$path,$m)&&$method==='POST'){require_csrf();if(!rate_limit('review',10,3600)){flash('error','Muitas tentativas. Aguarde para avaliar novamente.');redirect('/avaliar/'.$m[1]);}$s=db()->prepare("SELECT id,tenant_id,customer_name FROM orders WHERE tracking_token_hash=:token AND tracking_revoked_at IS NULL AND tracking_expires_at>NOW() AND status='delivered' LIMIT 1");$s->execute(['token'=>hash('sha256',$m[1])]);$order=$s->fetch();if(!$order){http_response_code(404);view('not-found');}$product=(int)($_POST['product_id']??0);$rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');$check=db()->prepare('SELECT 1 FROM order_items WHERE order_id=:order AND product_id=:product');$check->execute(['order'=>$order['id'],'product'=>$product]);if(!$check->fetchColumn()||$rating<1||$rating>5||strlen($comment)>1000){flash('error','Avaliação inválida.');redirect('/avaliar/'.$m[1]);}try{db()->prepare('INSERT INTO product_reviews (tenant_id,product_id,order_id,customer_name,rating,comment) VALUES (:tenant,:product,:order,:customer,:rating,:comment)')->execute(['tenant'=>$order['tenant_id'],'product'=>$product,'order'=>$order['id'],'customer'=>$order['customer_name'],'rating'=>$rating,'comment'=>$comment?:null]);audit((int)$order['tenant_id'],null,'create','product_review',(int)db()->lastInsertId(),['order_id'=>$order['id']]);flash('success','Avaliação enviada para moderação.');}catch(PDOException){flash('error','Este produto já foi avaliado neste pedido.');}redirect('/avaliar/'.$m[1]);}

if(preg_match('#^/avaliar/([a-f0-9]{64})/entrega$#',$path,$m)&&$method==='POST'){require_csrf();if(!rate_limit('courier-review',5,3600)){flash('error','Muitas tentativas. Aguarde para avaliar novamente.');redirect('/avaliar/'.$m[1]);}$s=db()->prepare("SELECT id,tenant_id,customer_name,assigned_courier_id FROM orders WHERE tracking_token_hash=:token AND tracking_revoked_at IS NULL AND tracking_expires_at>NOW() AND status='delivered' AND assigned_courier_id IS NOT NULL LIMIT 1");$s->execute(['token'=>hash('sha256',$m[1])]);$order=$s->fetch();if(!$order){http_response_code(404);view('not-found');}$rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');$courier=db()->prepare("SELECT 1 FROM users WHERE id=:courier AND tenant_id=:tenant AND role='courier'");$courier->execute(['courier'=>$order['assigned_courier_id'],'tenant'=>$order['tenant_id']]);if(!$courier->fetchColumn()||$rating<1||$rating>5||strlen($comment)>1000){flash('error','Avaliação inválida.');redirect('/avaliar/'.$m[1]);}try{db()->prepare('INSERT INTO courier_reviews (tenant_id,courier_id,order_id,customer_name,rating,comment) VALUES (:tenant,:courier,:order,:customer,:rating,:comment)')->execute(['tenant'=>$order['tenant_id'],'courier'=>$order['assigned_courier_id'],'order'=>$order['id'],'customer'=>$order['customer_name'],'rating'=>$rating,'comment'=>$comment?:null]);audit((int)$order['tenant_id'],null,'create','courier_review',(int)db()->lastInsertId(),['order_id'=>$order['id']]);flash('success','Avaliação da entrega enviada para moderação.');}catch(PDOException){flash('error','A entrega deste pedido já foi avaliada.');}redirect('/avaliar/'.$m[1]);}

